local ROLE, VERSION, SCHEMA = "gps", "4.0.0", 4
local EXPECTED_ASSEMBLED_DIGEST = "8dc345b7aa8a78ed47f49394ae7f236b3af1580d3f0276d2699b0a1d38c36275"
local partManifest = {
  { name = [[01.part]], bytes = 11986, digest = [[bd1be1b3587b972f5656a719ffc87ac7b3578a1252c87b18881ea2333deefd4e]] },
  { name = [[02.part]], bytes = 11958, digest = [[d935fa95f13f41d3fc70e288fa6b9c2cd877eccb8dff174f65b8c25f56397c41]] },
  { name = [[03.part]], bytes = 11980, digest = [[a3038e979e4cdb91d1435b8c05aba6aa63315a3db30d17e0ba9c6ff181ebb05f]] },
  { name = [[04.part]], bytes = 11990, digest = [[48fbfa789b8a7204bec39f3b5e6837130395449fe31302d766e03492c5fdc91c]] },
  { name = [[05.part]], bytes = 11946, digest = [[240fbbb8998156ec4eb438c6cfa635898c564d6ff896fed6d47646336b927bf9]] },
  { name = [[06.part]], bytes = 11994, digest = [[d2239186f20eabf66feb171d7ac11753e15a0219d5db859f80251c89134e1d53]] },
