  { name = [[09.part]], bytes = 11987, digest = [[6de32d6bd9ac84b73352efee78160eca9fa2c6a76cf9ead3fa49f90f426049ae]] },
  { name = [[10.part]], bytes = 11990, digest = [[a398dc97a655f54556ef3fa974ea9b8cbea2cec1e7196949bb2c075188913603]] },
  { name = [[11.part]], bytes = 11954, digest = [[408c71b6cc060c9086e4e168133ccbd733da70fd0eaede416a3cbf831578c5dd]] },
  { name = [[12.part]], bytes = 11996, digest = [[fb41b5a46242c9597f30ef9b49a57364395799045d9f5cc387de5d4df16db006]] },
  { name = [[13.part]], bytes = 11975, digest = [[8275e487b712937cf322b9389453ae3bc4d0e5b40ef86e1fa3e1d40f50336553]] },
